// Partner Organization Profile Retrieval
// Fetches the partner's organization profile from Partner Center API

var accessToken = input.get("accessToken");

if (!accessToken || accessToken.trim() === "") {
    log.error("Access Token is required");
    output.set("HasErrors", true);
    output.set("ErrorMessage", "Access Token is required");
    output.set("StatusCode", 0);
    tags.trigger("error");
} else {
    try {
        var url = "https://api.partnercenter.microsoft.com/v1/profiles/organization";

        log.info("Fetching partner organization profile");

        var response = http.get(url, {
            "Authorization": "Bearer " + accessToken.trim(),
            "Accept": "application/json"
        });

        output.set("StatusCode", response.statusCode);
        output.set("Body", response.body);

        if (response.statusCode >= 200 && response.statusCode < 300) {
            var profile = json.parse(response.body);

            // Organization identifiers
            output.set("OrganizationId", profile.id || "");
            output.set("TenantId", profile.tenantId || "");
            output.set("Domain", profile.domain || "");

            // Company info
            output.set("CompanyName", profile.companyName || "");
            output.set("Email", profile.email || "");
            output.set("Language", profile.language || "");
            output.set("Culture", profile.culture || "");
            output.set("ProfileType", profile.profileType || "");

            // Default address
            var addr = profile.defaultAddress || {};
            output.set("Country", addr.country || "");
            output.set("City", addr.city || "");
            output.set("PostalCode", addr.postalCode || "");
            output.set("AddressLine1", addr.addressLine1 || "");

            // Contact from address
            output.set("ContactFirstName", addr.firstName || "");
            output.set("ContactLastName", addr.lastName || "");
            output.set("ContactPhone", addr.phoneNumber || "");

            // ETag for caching/updates
            var attrs = profile.attributes || {};
            output.set("ETag", attrs.etag || "");

            output.set("HasErrors", false);
            output.set("ErrorMessage", "");

            log.info("Successfully retrieved organization profile for: " + (profile.companyName || "Partner"));
            tags.trigger("success");
        } else {
            var errorMsg = "API returned status " + response.statusCode;
            try {
                var errorBody = json.parse(response.body);
                if (errorBody.message) errorMsg = errorBody.message;
                else if (errorBody.error_description) errorMsg = errorBody.error_description;
            } catch (e) {
                if (response.body) errorMsg = response.body.substring(0, 500);
            }

            log.error("Failed to retrieve organization profile: " + errorMsg);
            output.set("HasErrors", true);
            output.set("ErrorMessage", errorMsg);
            tags.trigger("error");
        }
    } catch (ex) {
        log.error("Request failed: " + ex.message);
        output.set("HasErrors", true);
        output.set("ErrorMessage", "Request failed: " + ex.message);
        output.set("StatusCode", 0);
        tags.trigger("error");
    }
}
